/** Decode a country's rings to [lon, lat] degree pairs. Cached — callers may call it per frame. */
const _cache = new Map();
export function ringsOf(c) {
  if (_cache.has(c.n)) return _cache.get(c.n);
  const out = c.r.map((flat) => {
    const pts = new Array(flat.length / 2);
    let x = 0, y = 0;
    for (let i = 0; i < flat.length; i += 2) {
      x += flat[i]; y += flat[i + 1];
      pts[i / 2] = [x / 100, y / 100];
    }
    return pts;
  });
  _cache.set(c.n, out);
  return out;
}
export const borderCount = () => BORDER_COUNTRIES.length;

