const _ac = new WeakMap();
export function arcPoints(flat) {
  let c = _ac.get(flat); if (c) return c;
  const pts = new Array(flat.length / 2);
  let x = 0, y = 0;
  for (let i = 0; i < flat.length; i += 2) { x += flat[i]; y += flat[i + 1]; pts[i / 2] = [x / 100, y / 100]; }
  _ac.set(flat, pts);
  return pts;
}
